/** Her allowance: so much a week from your cash into a purse that's hers to spend (engine/allowance). */
function AllowanceRow({ id }: { id: string }) {
  const { save, mutate } = useGame();
  const p = save.people[id];
  const [draft, setDraft] = useState(String(allowanceOf(p) || ""));
  if (p.status !== "owned" && p.status !== "indentured") return null;
  const set = (n: number) => { mutate((s) => { setAllowance(s.people[id], n); }); setDraft(n ? String(n) : ""); };
  return (
    <div className="mt-3 pt-3 border-t text-[12px]" style={{ borderColor: "rgba(255,255,255,0.08)" }}>
      <div className="flex flex-wrap items-center gap-2">
        <span className="dim">allowance a week, hers to spend</span>
        <input className="!w-28" inputMode="numeric" value={draft} placeholder="0" onChange={(e) => setDraft(e.target.value.replace(/[^\d]/g, ""))} />
        <Button size="sm" onClick={() => set(Number(draft) || 0)}>set</Button>
        {allowanceOf(p) ? <Button size="sm" kind="ghost" onClick={() => set(0)}>stop it</Button> : null}
        <span className="ml-auto"><span className="dim">in her purse </span><Money n={purseOf(p)} /></span>
      </div>
      <div className="dim mt-1">Paid from your cash every week. She spends it on her own, and you'll hear what on. Saying it in a scene works too, like "I'll give you 100k a week".</div>
    </div>
  );
}

/** How big her memory is, and a button to boil it down now (engine/condense). */
function Condense({ id }: { id: string }) {
  const { save, mutate } = useGame();
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState("");
  const mem = save.memory[id];
  const p = save.people[id];
  if (!mem || !p) return null;
  const go = async () => {
    setBusy(true); setNote("");
    const r = await condenseMemory(save, p, { force: true });
    mutate(() => {});
    setNote(r.note);
    setBusy(false);
  };
  return (
    <div className="flex items-center gap-2 text-[11.5px] dim my-1.5">
      <span>{mem.episodic.length} memories, about {memoryTokens(mem).toLocaleString()} tokens{mem.condensed_week !== undefined ? `, last condensed week ${mem.condensed_week}` : ""}</span>
      {modelsAvailable() ? <button className="underline" disabled={busy} title="One quick model call that merges and trims her older memories. Core memories and the last few weeks are kept as they are" onClick={() => void go()}>{busy ? "condensing…" : "condense"}</button> : null}
      {note ? <span>{note}</span> : null}
    </div>
  );
}

/** A story with her, now, instead of waiting for one to be offered (engine/saga storyWith). */
function StoryWith({ id }: { id: string }) {
  const { save, mutate } = useGame();
  const [open, setOpen] = useState(false);
  const [idea, setIdea] = useState("");
  const p = save.people[id];
  const story = running(save).find((x) => x.seed.people?.includes(id));
  if (!p) return null;
  if (story) return <div><div className="text-[11px] uppercase tracking-wider dim mb-1.5">Her story</div><SagaCard id={story.id} /></div>;
  if (!open) return <Button size="sm" kind="ghost" onClick={() => setOpen(true)}>Start a story with {p.name.split(" ")[0]}</Button>;
  return (
    <Card>
      <div className="text-[12.5px] mid mb-2">What should it be about? Say it your way, or leave it empty and the game builds it from what's going on with her. It branches on what you choose, chapter by chapter, and you can start it over or steer it whenever you like.</div>
      <textarea className="w-full min-h-[70px]" value={idea} onChange={(e) => setIdea(e.target.value)} placeholder={`e.g. ${p.name.split(" ")[0]} catches the eye of a rich regular at the club, and he wants to buy her`} />
      <div className="flex gap-2 mt-2">
        <Button size="sm" kind="primary" onClick={() => { mutate((s) => { storyWith(s, id, idea); }); setOpen(false); setIdea(""); }}>Start it</Button>
        <Button size="sm" kind="ghost" onClick={() => setOpen(false)}>Never mind</Button>
      </div>
      {!modelsAvailable() ? <div className="text-[11.5px] dim mt-2">Stories are written by the model, so you'll need one set up in Settings to begin it.</div> : null}
    </Card>
  );
}
