export interface Going {
  /** Cooldown key: the same pair, or the same woman and the same kind, sits out a few weeks. */
  key: string;
  kind: "between" | "outside" | "pursuit" | "fallout";
  main: Person;
  other?: Person;
  /** What the game knows that makes it live now. */
  facts: string[];
  weight: number;
}

const COOLDOWN = 3;

/** What her last few goings-on were about and who was in them. */
const recentFor = (s: SaveState, id: string, weeks = 8) => (s.goings_seen ?? []).filter((g) => (g.person === id) && s.arcology.week - g.week <= weeks);

/** What the owner has said or done about someone, from what they remember and the deeds that name
 *  them: so a tailor told to stop doesn't turn up next week as if nothing was said. */
function ownerWordOn(s: SaveState, name: string): string[] {
  const first = name.split(" ")[0];
  const deeds = (s.deeds ?? []).filter((d) => d.summary.includes(first)).slice(-2).map((d) => `week ${d.week}: ${d.summary}`);
  return deeds;
}

/** The big things lately: what the owner did in public, and what happened to the city. */
function bigLately(s: SaveState): string[] {
  const week = s.arcology.week;
  const out: string[] = [];
  for (const d of s.deeds ?? []) if (d.public && week - d.week <= 2) out.push(d.summary);
  for (const h of s.world?.headlines ?? []) if (week - h.week <= 1) out.push(h.text);
  for (const r of s.reports ?? []) if (week - r.week <= 1) for (const l of r.lines) if (l.weight >= 8 && !l.person) out.push(l.text.split(/\n/)[0]);
  return [...new Set(out)].slice(0, 3);
}

const household = (s: SaveState) => Object.values(s.people).filter((p) =>
  (p.status === "owned" || p.status === "indentured") && p.age >= 18 && !p.governs && p.psyche.state !== "broken" && !(p.health.recovery_weeks > 0));

function feeling(s: SaveState, a: Person, b: Person): string {
  const e = getEdge(s.edges, a.id, b.id);
  if (!e) return "";
  const w = e.warmth, t = e.trust, at = e.attraction;
  const bits = [
    w > 40 ? "close to her" : w > 15 ? "friendly with her" : w < -30 ? "can't stand her" : w < -10 ? "cool toward her" : "",
    t < -20 ? "doesn't trust her" : t > 40 ? "trusts her" : "",
    at > 50 ? "wants her" : at > 30 ? "is drawn to her" : "",
    e.roles.length ? `(${e.roles.join(", ")})` : "",
  ].filter(Boolean);
  return bits.length ? `${a.name} toward ${b.name}: ${bits.join(", ")}.` : "";
}

function job(s: SaveState, p: Person): string {
  const w = workplaceOf(s, p);
  return w.withYou ? `her place is with the owner (${p.assignment})` : `she works ${inPlace(w.name)} (${p.assignment})`;
}

/** Everything live between people this week. */
export function goingsCandidates(s: SaveState): Going[] {
  const week = s.arcology.week;
  const people = household(s);
  const out: Going[] = [];
  const report = s.reports.at(-1);
  const lines = report && report.week >= week - 1 ? report.lines.map((l) => l.text) : [];
  const first = (p: Person) => p.name.split(" ")[0];

  // Two of yours: only when the house rules have things between them come to you (engine/houserules).
  const pairs = betweenEvents(s) ? people : [];
  for (let i = 0; i < pairs.length; i++) for (let j = i + 1; j < pairs.length; j++) {
    const a = pairs[i], b = pairs[j];
    const ea = getEdge(s.edges, a.id, b.id), eb = getEdge(s.edges, b.id, a.id);
    const facts: string[] = [feeling(s, a, b), feeling(s, b, a)].filter(Boolean);
    let w = 1 + (Math.abs(ea?.warmth ?? 0) + Math.abs(eb?.warmth ?? 0)) / 50 + Math.max(ea?.attraction ?? 0, eb?.attraction ?? 0) / 50;
    const happened = lines.filter((l) => l.includes(first(a)) && l.includes(first(b))).slice(0, 2);
    if (happened.length) { facts.push(...happened.map((l) => `This week: ${l}`)); w += 2.5; }
    const recent = [a, b].flatMap((x) => (s.memory[x.id]?.episodic ?? []).filter((m) => week - m.week <= 3 && m.content.includes(first(x === a ? b : a))).slice(-1).map((m) => `${x.name} remembers, from week ${m.week}: ${m.content}`));
    if (recent.length) { facts.push(...recent); w += 1.2; }
    for (const [x, y] of [[a, b], [b, a]] as const) for (const m of x.manner ?? []) if (m.id === y.id || m.toward.includes(first(y))) { facts.push(`How ${x.name} is with ${y.name}: ${m.how}`); w += 0.8; }
    const la = latitudeOf(a), lb = latitudeOf(b);
    if (la !== lb) { const [hi, lo] = la === "free" || (la === "latitude" && lb === "slave") ? [a, b] : [b, a]; facts.push(`${hi.name} has more standing with the owner than ${lo.name} (${romanceOf(hi).standing} against ${romanceOf(lo).standing}), and both of them know it.`); w += 1; }
    if (a.assignment === b.assignment || (a.facility && a.facility === b.facility)) { facts.push(`They work together: ${job(s, a)}.`); w += 0.8; }
    facts.push(`${a.name}: ${job(s, a)}. ${b.name}: ${job(s, b)}.`);
    out.push({ key: `pair:${[a.id, b.id].sort().join(":")}`, kind: "between", main: a, other: b, facts, weight: w });
  }

  for (const p of people) {
    // One of yours and the people around her at work, or in her life outside.
    const where = workplaceOf(s, p);
    // Not the same outsider again: whoever was in her last goings-on sits out, and what the owner
    // said or did about the ones that remain comes with them.
    const lately = new Set(recentFor(s, p.id).flatMap((g) => g.who.map((w) => shortName(w) ?? w)));
    const ties = tiedTo(s, p.id).filter((t) => !t.face.fate && !lately.has(shortName(t.face.name) ?? t.face.name));
    const talk = s.rumors.filter((r) => r.about === p.id && r.week >= week - 2).slice(0, 1);
    const facts = [
      where.withYou ? `Her place is with the owner (${p.assignment}), and the people around her are the owner's guests, staff and visitors.` : `She works ${inPlace(where.name)}, which is ${where.look}. The people there are whoever works there or comes there.`,
      ...ties.slice(0, 3).map((t) => `In her life outside the house: ${t.face.name}, ${t.what}.`),
      ...ties.slice(0, 3).flatMap((t) => ownerWordOn(s, t.face.name).map((x) => `What the owner did about ${t.face.name}, which still stands: ${x}. If he told them to stop or keep away, they do, or if they come back it's tense and it costs them, never business as usual.`)),
      ...talk.map((r) => `People are saying: ${r.content}`),
    ];
    let w = 1.2 + (where.privacy === "public" ? 1.6 : where.withYou ? 0 : 0.6) + Math.min(1.5, ties.length * 0.8) + (talk.length ? 1 : 0);
    if (/cellblock|confined/.test(p.assignment ?? "")) w = 0;
    if (w > 0) out.push({ key: `out:${p.id}`, kind: "outside", main: p, facts, weight: w });

    // What she does with her own time, when someone else gets mixed up in it.
    // One of her interests at a time, a different one each time, so her own time isn't one subject.
    const does = p.persona.interests ?? [], wants = p.persona.goals ?? [];
    const turn = recentFor(s, p.id, 52).filter((g) => g.key.startsWith("own:")).length;
    if (does.length || wants.length) out.push({
      key: `own:${p.id}`, kind: "pursuit", main: p, weight: 1 + (wants.length ? 0.4 : 0),
      facts: [
        does.length ? `What she does with her own time, the part this is about: ${sentences([does[turn % does.length]])}` : "",
        wants.length ? `What she wants in the long run: ${sentences([wants[turn % wants.length]])}` : "",
        `Someone else gets involved in it this week, ${betweenEvents(s) ? "another of the owner's women, " : ""}someone where she works, or a citizen.`,
      ].filter(Boolean),
    });

    // When something big has happened, how it lands on her and the people around her.
    const big = bigLately(s);
    if (big.length) out.push({
      key: `fallout:${p.id}`, kind: "fallout", main: p, weight: 2.4,
      facts: [
        `What happened in the arcology lately: ${big.join(" | ")}`,
        `This event is about how that lands on ${p.name} and the people around her, where she works or lives or in her life outside. That could be fear, damage, opportunity, people blaming her or wanting something from her because of whose she is, or a person from her life caught up in it.`,
        where.withYou ? `Her place is with the owner (${p.assignment}).` : `She works ${inPlace(where.name)}.`,
        ...ties.slice(0, 2).map((t) => `In her life outside the house: ${t.face.name}, ${t.what}.`),
      ],
    });
  }
  return out;
}

/** This week's one or two, by how live they are, nobody's twice and nothing that came up lately. */
export function pickGoings(s: SaveState): Going[] {
  const week = s.arcology.week;
  const log = s.event_log ?? {};
  const pool = goingsCandidates(s).filter((g) => week - (log[`going:${g.key}`] ?? -99) >= COOLDOWN);
  if (!pool.length) return [];
  const r = rng(`goings:${s.arcology.name}:${week}`);
  const busy = new Set(s.events.filter((e) => e.week === week).flatMap((e) => [e.person, e.other]).filter(Boolean));
  const want = 1 + (household(s).length >= 3 || r.chance(0.5) ? 1 : 0);
  const out: Going[] = [];
  const used = new Set<string>();
  for (let k = 0; k < want; k++) {
    const left = pool.filter((g) => !used.has(g.main.id) && !(g.other && used.has(g.other.id)) && !out.includes(g));
    if (!left.length) break;
    // Someone already in an event this week can still be in one, but less likely.
    const g = r.weighted(left, (x) => x.weight * (busy.has(x.main.id) ? 0.4 : 1));
    out.push(g);
    used.add(g.main.id);
    if (g.other) used.add(g.other.id);
  }
  return out;
}

export const GOING_SYSTEM = `You write one event for Free Cities, an adult text game about owning an arcology where slavery is legal and ordinary. It is NOT one of the owner's slaves wanting something from the owner. It's something going on between people that the owner comes across, walks in on or hears about, and can get involved in. The people can be two of the owner's slaves, or one of them and someone outside the household, like a customer, a coworker, her boss, a citizen, a guard, somebody else's slave, or someone from her life before.

How to build it:
- Start from THE FACTS. They're true, and they're why it's happening now. Build it out of them, the people's natures, how they feel about each other, where they are, and this week.
- It happens in the same world as everything else. Tie it into WHAT ELSE IS GOING ON and THIS WEEK where it fits, so people know what the owner did and what happened to the city, it's on their minds, it changes what they want, and it can be the reason the event happens. Mix threads rather than following one on its own.
- It's NOT a continuation of her recent goings-on (listed under HER RECENT GOINGS-ON). Pick a different subject, a different place and different people. Someone the owner told to stop or keep away doesn't carry on as if nothing was said.
- It happens somewhere real, like where she works, somewhere in the house, or on the concourse. Say where.
- ${NOT_PAPERWORK}
- This is an adult game and sex is most of what happens between people in it. Something is actually happening, with a shape, and more often than not it's sexual, like a customer who gets rough, a coworker or her boss with his hands on her, a crowd gathering to watch, or a client who wants her for a whole night. Between two of the owner's own women, only what BETWEEN THEM below allows. It can also be a quarrel, a favour, a dare, a secret found out or a competition, but it doesn't have to stay clean. Their fetishes, bodies and what they're into (on their cards) decide what it is. Write the sex as plainly as the rest. It's not a mood and it's not a status report.
- People act as their place allows. A slave is a slave to the owner (see THE POWER BETWEEN YOU on her card), and outsiders know who the owner is.
- An outsider in it who has no name yet gets a name and one detail, and goes under "cast". The owner's own women are never outsiders and never go under "cast", and an outsider never has the name of one of them. Everyone is eighteen or older.
- Write one or two short paragraphs in the second person and the present tense, ending where the owner can step in, with their words in their own voices, short and plain.

Then give three or four really different choices for the owner. Two are ways of getting involved, like joining in, taking one of them, making them do it in front of you, taking a side, using it, putting a stop to it, or making it worse. When it's sexual, at least one of those is the owner getting in on it (effect "act" with an act id, "on" the one he takes, or "both"). At least one choice leaves them to it. Each choice has an effect from EFFECT IDS and an "on", which is "main" for the first of the owner's women in THE PEOPLE, "other" for the second if there is one, or "both". The effects that are about the two of them together land on both whatever "on" says.

${HOUSE_STYLE}

Output ONE strict JSON object and nothing else:
{"title":"2-5 words","situation":"...","options":[{"label":"what you do, 2-9 words","note":"a few plain words for the player, like \\"she won't forget it\\", and never the effect's description","effect":"effect id","on":"main","value":"optional"}],"hook":"what this leaves open for later, or empty","cast":[{"name":"...","pronoun":"she or he","what":"who they are, a few words","to_her":"what they are to her, a few words"}]}`;

/** What may happen between two of your own women, by the house rules. */
function betweenThem(s: SaveState): string {
  if (!sexBetween(s)) return "Nothing sexual happens between these two, because the house rules keep it to everything else, like a quarrel, a favour, a rivalry, a friendship, a theft or a secret.";
  if (!forcedAllowed(s)) return "It can be sexual between them (two of the girls fucking in the showers, one teaching the other how to suck cock, a crush turning into her mouth between the other's legs), always with both of them willing, because no slave forces another.";
  return "It can be sexual between them (two of the girls fucking in the showers, one teaching the other how to suck cock, a crush turning into her mouth between the other's legs), and the house rules let one take the other whether she wants it or not.";
}

/** Write one of them. Null when there's no model or it came back unusable. */
export async function generateGoing(s: SaveState, g: Going, snapshot = ""): Promise<PendingEvent | null> {
  if (!modelsAvailable() || s.models.lean_mode) return null;
  const pair = Object.keys(PAIR_EFFECTS).map((k) => `${k}: ${PAIR_EFFECTS[k].note}`);
  const people = [g.main, g.other].filter((x): x is Person => !!x);
  const res = await call({ narration: true, tag: "goings",
    system: GOING_SYSTEM,
    user: [
      snapshot,
      `## THE PEOPLE\n${people.map((p, i) => `### ${i === 0 ? "MAIN" : "OTHER"}\n${personCard(s, p, g.facts.join(" "))}`).join("\n\n")}`,
      castBrief(s, g.facts.join("\n")),
      chronicleBrief(s, people.map((p) => p.id), 6),
      cityPicture(s),
      aroundBrief(s),
      recentFor(s, g.main.id).length ? `## HER RECENT GOINGS-ON\nThis one is about something else.\n${recentFor(s, g.main.id).map((x) => `· week ${x.week}: ${x.title ?? x.topic ?? "something"}${x.who.length ? `, with ${x.who.join(", ")}` : ""}`).join("\n")}` : "",
      `## THE FACTS\n${g.facts.map((f) => `· ${f}`).join("\n")}`,
      rulesLine(s),
      g.other ? `## BETWEEN THEM\n${[betweenThem(s), pairFitLine(s, g.main, g.other), pairFitLine(s, g.other, g.main)].filter(Boolean).join("\n")}` : "",
      `## EFFECT IDS\n${effectList()}${g.other ? `\n${pair.join("\n")}` : ""}\nACT IDS (for "act"): ${Object.keys(ACT_BY_ID).join(", ")}`,
      PLAIN_RULES,
      REGISTER_TAIL,
    ].filter(Boolean).join("\n\n"),
    model: s.models.narrator_model,
    fallback: s.models.fallback_model,
    json: true,
    maxTokens: 1400,
    temperature: 0.95,
  });
  if (!res.ok) return null;
  const out = parseJson<{ title?: string; situation?: string; hook?: string; options?: { label?: string; note?: string; effect?: string; on?: string; value?: string | number }[]; cast?: { name?: string; pronoun?: string; what?: string; to_her?: string }[] }>(coarsen(res.text));
  if (!out?.situation || !Array.isArray(out.options)) return null;
  const known = (id: string) => !!DYNAMIC_EFFECTS[id] || (!!g.other && !!PAIR_EFFECTS[id]);
  const on = (x?: string) => (g.other && (x === "other" || x === "both") ? x : "main");
  const options = out.options.filter((o) => o?.label && o.effect && known(String(o.effect))).slice(0, 4)
    .map((o, i) => ({ id: `g${i}:${o.effect}@${on(o.on)}:${String(o.value ?? "").replace(/:/g, " ")}`, label: String(o.label).slice(0, 80), note: o.note ? String(o.note).slice(0, 90) : undefined }));
  if (options.length < 2) return null;

  const week = s.arcology.week;
  const situation = String(out.situation).slice(0, 2400);
  if (isBanned(s, `${out.title ?? ""} ${situation} ${out.hook ?? ""}`)) return null;
  // Whoever the model brought in goes on file, tied to her, so they can turn up again.
  for (const c of (Array.isArray(out.cast) ? out.cast : []).slice(0, 2)) {
    const name = String(c?.name ?? "").trim();
    if (!name || people.some((p) => p.name.split(" ")[0] === name.split(" ")[0])) continue;
    const f = file(s, name.slice(0, 48), String(c.what ?? "").slice(0, 80) || "someone she knows", c.pronoun === "he" ? "he" : "she");
    if (!f) continue;
    if (c.to_her) tie(f, String(c.to_her), g.main.id);
    note(s, f, partIn(situation, name));
  }
  (s.event_log ??= {})[`going:${g.key}`] = week;
  // What it was about and who was in it, so the next ones go somewhere else.
  const who = [...new Set([...(Array.isArray(out.cast) ? out.cast : []).map((c) => String(c?.name ?? "").trim()).filter(Boolean), ...facesIn(s, situation, 4).map((f) => f.name)])].slice(0, 4);
  s.goings_seen = [...(s.goings_seen ?? []), { week, person: g.main.id, key: g.key, title: out.title ? String(out.title).slice(0, 60) : undefined, who, topic: situation.slice(0, 80) }].slice(-30);
  return {
    id: `going-${week}-${g.main.id}${g.other ? `-${g.other.id}` : ""}`,
    kind: "dynamic",
    person: g.main.id,
    other: g.other?.id,
    seed: situation,
    options,
    week,
    severity: "notable",
    written: { model: res.model, title: out.title ? String(out.title).slice(0, 60) : undefined },
    hook: out.hook ? String(out.hook).slice(0, 200) : undefined,
  };
}
